function cx(...values: Array<string | false | null | undefined>) { return values.filter(Boolean).join(' '); }
function Alert({ children, tone = 'warning' }: { children: ReactNode; tone?: 'warning' | 'error' | 'success' | 'info' }) {
  const styles = { warning: 'bg-amber-50 border-amber-200 text-amber-950', error: 'bg-rose-50 border-rose-200 text-rose-900', success: 'bg-emerald-50 border-emerald-200 text-emerald-950', info: 'bg-teal-50 border-teal-200 text-teal-950' };
  return <div className={cx('flex gap-3 rounded-xl border p-4 text-sm leading-6', styles[tone])}><Info size={18} className="mt-1 shrink-0" /><div>{children}</div></div>;
}
function Button({ children, className = '', variant = 'primary', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'secondary' | 'quiet' | 'danger' }) {
  return <button className={cx('inline-flex min-h-11 items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-bold transition duration-150 disabled:cursor-not-allowed disabled:opacity-50', variant === 'primary' && 'bg-primary text-primary-foreground hover:brightness-95', variant === 'secondary' && 'border border-border bg-card text-foreground hover:bg-muted', variant === 'quiet' && 'text-primary hover:bg-emerald-50', variant === 'danger' && 'bg-rose-700 text-white hover:bg-rose-800', className)} {...props}>{children}</button>;
}
function PageTitle({ eyebrow, title, sub, action }: { eyebrow?: string; title: string; sub?: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div>{eyebrow && <p className="mb-2 text-xs font-bold uppercase tracking-[.16em] text-primary">{eyebrow}</p>}<h1 className="font-[var(--app-font-serif)] text-3xl font-extrabold tracking-tight text-foreground sm:text-[2.55rem]">{title}</h1>{sub && <p className="mt-2 max-w-2xl text-base leading-7 text-muted-foreground">{sub}</p>}</div>{action}</div>;
}
function Skeleton({ className = '' }: { className?: string }) { return <div className={cx('animate-pulse rounded-xl bg-muted', className)} />; }
function LoadError({ retry }: { retry?: () => void }) { return <div className="grid gap-3 rounded-2xl border border-rose-200 bg-rose-50 p-6"><p className="font-bold text-rose-900">We could not load this information.</p><p className="text-sm text-rose-800">Check your connection and try again. Your account information remains private.</p>{retry && <Button variant="secondary" onClick={retry}><RefreshCw size={16} /> Try again</Button>}</div>; }
function DataMark({ status = 'demo_unverified' }: { status?: string | null }) {
  if (status === 'official_verified') return <span className="inline-flex items-center gap-1.5 rounded-full border border-emerald-300 bg-emerald-50 px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-[.12em] text-emerald-900"><BadgeCheck size={12} /> Source verified</span>;
  return <span className="inline-flex items-center gap-1.5 rounded-full border border-amber-300 bg-amber-50 px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-[.12em] text-amber-900"><AlertTriangle size={12} /> Demo · not verified</span>;
}
function StatusPill({ status }: { status: string }) {
  const human = status.replaceAll('_', ' ');
  return <span className="rounded-full bg-muted px-3 py-1 text-xs font-bold capitalize text-foreground">{human}</span>;
}

function SchemeCard({ scheme, saved = false, onSave }: { scheme: Scheme; saved?: boolean; onSave?: (id: string) => void }) {
  return <article className="group flex h-full flex-col rounded-2xl border border-border bg-card p-5 shadow-sm transition hover:-translate-y-0.5 hover:shadow-md sm:p-6" data-testid={`card-scheme-${scheme.id}`}>
    <div className="mb-4 flex items-start justify-between gap-3"><span className="rounded-md bg-emerald-50 px-2.5 py-1 text-xs font-bold text-primary">{scheme.category}</span><DataMark status={scheme.dataStatus} /></div>
    <Link href={`/schemes/${scheme.id}`} className="font-[var(--app-font-serif)] text-xl font-extrabold leading-snug text-foreground hover:text-primary" data-testid={`link-scheme-${scheme.id}`}>{scheme.schemeName}</Link>
    <p className="mt-2 text-sm leading-6 text-muted-foreground">{scheme.description}</p>
    <div className="mt-4 rounded-xl bg-[#f3f4e9] p-3.5"><p className="text-[11px] font-extrabold uppercase tracking-widest text-primary">Potential benefit</p><p className="mt-1 text-sm font-semibold leading-5 text-foreground">{scheme.benefit}</p></div>
    <div className="mt-4 flex items-center gap-2 text-xs text-muted-foreground"><Landmark size={14} />{scheme.government}{scheme.state ? ` · ${scheme.state}` : ' · Central'}</div>
    <div className="mt-auto flex items-center justify-between gap-2 pt-5">
      <Link href={`/schemes/${scheme.id}`} className="inline-flex min-h-10 items-center gap-2 text-sm font-bold text-primary">View guidance <ArrowRight size={15} /></Link>
      {onSave && <Button variant="secondary" className="min-h-10 px-3" aria-label={saved ? 'Remove saved scheme' : 'Save scheme'} onClick={() => onSave(scheme.id)}><Heart size={16} fill={saved ? 'currentColor' : 'none'} />{saved ? 'Saved' : 'Save'}</Button>}
    </div>
  </article>;
}

function Shell({ children }: { children: ReactNode }) {
  const [location, setLocation] = useLocation();
  const [open, setOpen] = useState(false);
  const { data: auth } = useGetCurrentUser();
  const logout = useLogout();
  const qc = useQueryClient();
  const isAuth = location === '/login' || location === '/register';
  const active = (href: string) => location === href || (href === '/schemes' && location.startsWith('/schemes/'));
  return <div className="grain min-h-[100dvh] bg-background text-foreground">
    <header className="sticky top-0 z-30 border-b border-border bg-background/95 backdrop-blur">
      <div className="mx-auto flex h-[72px] max-w-[1440px] items-center justify-between px-4 sm:px-7">
        <Link href="/" className="flex items-center gap-3" aria-label="SchemeSaathi home"><span className="grid h-10 w-10 place-items-center rounded-xl bg-primary text-primary-foreground"><Landmark size={22} /></span><span><span className="block font-[var(--app-font-serif)] text-lg font-extrabold leading-tight">SchemeSaathi</span><span className="block text-[10px] font-bold uppercase tracking-[.13em] text-muted-foreground">A clearer path to support</span></span></Link>
        <div className="hidden items-center gap-2 md:flex">{!isAuth && <><Link href="/help" className="rounded-lg px-3 py-2 text-sm font-semibold text-muted-foreground hover:text-primary">Help</Link>{auth?.user ? <><Link href="/profile" className="flex items-center gap-2 rounded-xl border border-border px-3 py-2 text-sm font-semibold"><CircleUserRound size={17} />{auth.user.fullName}</Link><Button variant="quiet" onClick={() => logout.mutate(undefined, { onSuccess: () => { qc.setQueryData(getGetCurrentUserQueryKey(), null); setLocation('/'); } })}><LogOut size={16} /> Sign out</Button></> : <Link href="/login" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary px-4 py-2 text-sm font-bold text-primary-foreground"><LogIn size={16} /> Sign in</Link>}</>}</div>
        <button aria-label="Open navigation" onClick={() => setOpen(v => !v)} className="rounded-xl border border-border p-2 md:hidden">{open ? <X size={21} /> : <Menu size={21} />}</button>
      </div>
      {open && <div className="border-t border-border bg-card px-4 py-3 md:hidden"><div className="grid gap-1">{[...navItems, { href: '/help', label: 'Help & support', icon: CircleHelp }, { href: '/profile', label: 'My profile', icon: UserRound }].map(item => <Link key={item.href} href={item.href} onClick={() => setOpen(false)} className="flex min-h-11 items-center gap-3 rounded-lg px-3 text-sm font-semibold hover:bg-muted"><item.icon size={18} />{item.label}</Link>)}<Link href="/login" onClick={() => setOpen(false)} className="flex min-h-11 items-center gap-3 rounded-lg px-3 text-sm font-semibold hover:bg-muted"><LogIn size={18} />Sign in</Link></div></div>}
    </header>
    <div className="mx-auto flex max-w-[1440px]">
      {!isAuth && location !== '/' && <aside className="sticky top-[72px] hidden h-[calc(100dvh-72px)] w-[250px] shrink-0 flex-col border-r border-border bg-[#f1f2e9] px-4 py-7 lg:flex">
        <p className="mb-3 px-3 text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Your Saathi space</p>
        <nav className="grid gap-1">{navItems.map(item => <Link key={item.href} href={item.href} className={cx('flex min-h-11 items-center gap-3 rounded-xl px-3 text-sm font-semibold transition', active(item.href) ? 'bg-primary text-primary-foreground shadow-sm' : 'text-foreground/75 hover:bg-white/70 hover:text-primary')}><item.icon size={18} strokeWidth={1.8} />{item.label}</Link>)}</nav>
        {auth?.user?.role === 'admin' && <div className="mt-7 border-t border-border pt-5"><p className="mb-2 px-3 text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Administration</p><Link href="/admin" className="flex min-h-11 items-center gap-3 rounded-xl px-3 text-sm font-semibold text-foreground/75 hover:bg-white/70"><SlidersHorizontal size={18} />Manage schemes</Link></div>}
        <div className="mt-auto rounded-2xl border border-[#d9ddcc] bg-[#e5eadb] p-4"><ShieldCheck size={20} className="text-primary" /><p className="mt-2 text-sm font-bold">Your information stays yours.</p><p className="mt-1 text-xs leading-5 text-muted-foreground">We help you understand options. Only an official authority can approve an application.</p></div>
      </aside>}
      <main className={cx('min-w-0 flex-1', location === '/' ? '' : 'px-4 py-8 sm:px-7 sm:py-10 lg:px-10')}><div className={location === '/' ? '' : 'page-enter mx-auto max-w-[1120px]'}>{children}</div></main>
    </div>
    <footer className="border-t border-border bg-card px-5 py-6 text-center text-xs text-muted-foreground">SchemeSaathi is an information guide, not a government authority. Always confirm current rules with the official source.</footer>
  </div>;
}

function HomePage() {
  const { data: schemes, isLoading } = useListSchemes();
  return <div>
    <section className="relative overflow-hidden bg-[#e9eee2]">
      <div className="mx-auto grid max-w-[1300px] items-center gap-10 px-5 py-14 sm:px-9 sm:py-20 lg:grid-cols-[1.08fr_.92fr] lg:px-12 lg:py-24">
        <div className="relative z-10"><div className="mb-6 inline-flex items-center gap-2 rounded-full border border-[#cad7c7] bg-[#f6f7ef] px-3 py-1.5 text-xs font-bold text-primary"><ShieldCheck size={15} /> Clear information. Your decision.</div><h1 className="max-w-[720px] font-[var(--app-font-serif)] text-[2.75rem] font-extrabold leading-[1.05] tracking-[-.045em] text-[#1d382f] sm:text-6xl lg:text-[4.45rem]">Find support that fits <span className="text-primary">your life.</span></h1><p className="mt-6 max-w-xl text-lg leading-8 text-[#50675c]">A practical guide to welfare schemes, eligibility clues and the documents you may need. In English, Hindi or Telugu.</p><div className="mt-8 flex flex-col gap-3 sm:flex-row"><Link href="/eligibility" className="inline-flex min-h-12 items-center justify-center gap-2 rounded-xl bg-primary px-6 text-sm font-bold text-white shadow-sm hover:brightness-95">Check what may fit <ArrowRight size={17} /></Link><Link href="/schemes" className="inline-flex min-h-12 items-center justify-center gap-2 rounded-xl border border-[#becbbd] bg-[#f6f7ef] px-6 text-sm font-bold text-[#1d382f]">Browse all schemes <BookOpen size={17} /></Link></div><p className="mt-5 text-xs font-medium text-[#66786d]">Free to explore · Private by design · No approval promises</p></div>
        <div className="relative min-h-[320px] lg:min-h-[420px]"><div className="absolute right-[5%] top-[5%] h-[84%] w-[82%] rounded-[48%_42%_38%_45%] bg-[#d0ddc9]" /><div className="absolute right-[10%] top-[2%] grid h-[88%] w-[78%] place-items-center overflow-hidden rounded-[44%_46%_38%_42%] bg-[#d9e5d4]"><div className="absolute inset-x-0 bottom-0 h-[38%] bg-[#bbcbb7]" /><div className="absolute bottom-[24%] left-[20%] h-[43%] w-[59%] rounded-t-[46%] bg-[#f6d99d]" /><div className="absolute bottom-[19%] left-[12%] h-[14%] w-[76%] rounded-[50%] bg-[#3d6e59]" /><div className="absolute bottom-[50%] left-[37%] h-20 w-20 rounded-full bg-[#b86f4b]" /><div className="absolute bottom-[36%] left-[24%] h-[30%] w-[44%] rounded-t-[44%] bg-[#2f5646]" /><div className="absolute bottom-[22%] right-[15%] h-[35%] w-[27%] rounded-t-[45%] bg-[#ca8d55]" /><div className="absolute bottom-[49%] right-[19%] h-14 w-14 rounded-full bg-[#986248]" /><div className="absolute right-[14%] top-[14%] h-24 w-24 rounded-full border-[14px] border-[#e9be68]" /><div className="absolute left-[10%] top-[14%] h-10 w-10 rounded-full bg-[#f8f4e8]" /></div><div className="absolute bottom-[11%] left-[0] rounded-2xl border border-white/70 bg-[#fbfaf2] p-4 shadow-md"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#e8efdf] text-primary"><ListChecks size={21} /></span><div><p className="text-xs font-bold text-primary">A clear next step</p><p className="text-sm font-bold text-foreground">One question at a time</p></div></div></div><div className="absolute right-[1%] top-[13%] rotate-3 rounded-xl bg-[#fffaf0] px-4 py-3 shadow-md"><p className="text-xs font-bold text-[#6b5a31]">You stay in control.</p></div></div>
      </div>
    </section>
    <section className="mx-auto max-w-[1200px] px-5 py-16 sm:px-9 lg:px-12"><div className="grid gap-10 lg:grid-cols-[.7fr_1.3fr]"><div><p className="text-xs font-extrabold uppercase tracking-[.15em] text-primary">A simpler way forward</p><h2 className="mt-3 font-[var(--app-font-serif)] text-3xl font-extrabold tracking-tight sm:text-4xl">Good guidance starts with your situation.</h2><p className="mt-4 leading-7 text-muted-foreground">Tell us a little about yourself, then explore schemes that could be relevant. You can skip anything you do not know.</p></div><div className="grid gap-3 sm:grid-cols-3">{[{n:'01',t:'Share what matters',b:'Your age, location and circumstances help narrow the search.'},{n:'02',t:'Understand the fit',b:'See matched details, open questions and documents to gather.'},{n:'03',t:'Take the next step',b:'Use the official source to confirm details and apply.'}].map(x=><div key={x.n} className="rounded-2xl border border-border bg-card p-5"><span className="font-mono text-sm font-bold text-[#b47d38]">{x.n}</span><h3 className="mt-5 font-bold">{x.t}</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">{x.b}</p></div>)}</div></div></section>
    <section className="bg-[#f0f1e8] px-5 py-14 sm:px-9 lg:px-12"><div className="mx-auto max-w-[1200px]"><div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-extrabold uppercase tracking-[.15em] text-primary">Start exploring</p><h2 className="mt-2 font-[var(--app-font-serif)] text-3xl font-extrabold">A few places to begin</h2></div><Link href="/schemes" className="text-sm font-bold text-primary">View scheme catalogue <ArrowRight className="ml-1 inline" size={15} /></Link></div>{isLoading ? <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{[1,2,3].map(n=><Skeleton key={n} className="h-56" />)}</div> : schemes?.length ? <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{schemes.slice(0,3).map(s=><SchemeCard key={s.id} scheme={s} />)}</div> : <Alert>No schemes are available right now. Please check again later.</Alert>}</div></section>
    <section className="mx-auto grid max-w-[1200px] gap-8 px-5 py-16 sm:px-9 lg:grid-cols-2 lg:px-12"><div className="rounded-[28px] bg-[#173d32] p-7 text-[#f8f7ef] sm:p-10"><Languages size={28} className="text-[#f0ca7a]" /><h2 className="mt-5 font-[var(--app-font-serif)] text-3xl font-extrabold">Ask in a language you are comfortable with.</h2><p className="mt-3 max-w-md leading-7 text-[#d0dbd2]">Get grounded answers in English, Hindi or Telugu, with sources shown alongside the response.</p><Link href="/assistant" className="mt-6 inline-flex min-h-11 items-center gap-2 rounded-xl bg-[#f0ca7a] px-4 text-sm font-bold text-[#1a392f]">Talk to Saathi <MessageCircle size={16} /></Link></div><div className="flex flex-col justify-center"><p className="text-xs font-extrabold uppercase tracking-[.15em] text-primary">Built for clarity</p><h2 className="mt-2 font-[var(--app-font-serif)] text-3xl font-extrabold">Useful, careful, and never a promise of approval.</h2><ul className="mt-5 grid gap-3 text-sm leading-6 text-muted-foreground">{['Eligibility clues are guidance, not a decision by a government office.','Scheme sources and last-updated details remain visible.','Your personal documents are private and are not public.'].map(t=><li key={t} className="flex gap-3"><Check className="mt-1 shrink-0 text-primary" size={17} />{t}</li>)}</ul></div></section>
  </div>;
}

function DashboardPage() {
  const { data, isLoading, isError, refetch } = useGetDashboard();
  const { data: profile } = useGetProfile();
  if (isLoading) return <div className="grid gap-5"><Skeleton className="h-24" /><div className="grid gap-4 sm:grid-cols-3">{[1,2,3].map(n=><Skeleton key={n} className="h-28" />)}</div><Skeleton className="h-64" /></div>;
  if (isError || !data) return <LoadError retry={() => refetch()} />;
  return <><PageTitle eyebrow="Your overview" title={`Welcome${profile?.fullName ? `, ${profile.fullName.split(' ')[0]}` : ' back'}`} sub="A helpful place to see your progress and what you can do next." action={<Link href="/profile" className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-border bg-card px-4 text-sm font-bold"><UserRound size={17} /> Complete profile</Link>} />
    <Alert>Scheme information may be seeded for demonstration. Check the official source before relying on any eligibility rule, benefit or deadline. A match is not an approval.</Alert>
    <div className="mt-6 grid gap-4 sm:grid-cols-3">{[{label:'Possible matches',value:data.eligibleCount,icon:BadgeCheck,href:'/eligibility'},{label:'Saved for later',value:data.savedCount,icon:Heart,href:'/saved'},{label:'Documents added',value:data.documentCount,icon:FileCheck2,href:'/documents'}].map(s=><Link key={s.label} href={s.href} className="flex items-center justify-between rounded-2xl border border-border bg-card p-5 shadow-sm"><div><p className="text-sm font-semibold text-muted-foreground">{s.label}</p><p className="mt-2 font-mono text-3xl font-bold">{s.value}</p></div><s.icon className="text-primary" size={25} /></Link>)}</div>
    <section className="mt-9"><div className="mb-4 flex items-end justify-between"><div><p className="text-xs font-extrabold uppercase tracking-[.15em] text-primary">Suggested for you</p><h2 className="mt-1 font-[var(--app-font-serif)] text-2xl font-extrabold">A few options to explore</h2></div><Link href="/schemes" className="text-sm font-bold text-primary">Browse all</Link></div>{data.recommendations.length ? <div className="grid gap-4 md:grid-cols-2">{data.recommendations.slice(0,4).map(s=><SchemeCard key={s.id} scheme={s} />)}</div> : <div className="rounded-2xl border border-dashed border-border bg-card p-8 text-center"><BookOpen className="mx-auto text-primary" /><h3 className="mt-3 font-bold">Your options will appear here</h3><p className="mt-1 text-sm text-muted-foreground">Add profile details or browse the catalogue to get started.</p><Link href="/eligibility" className="mt-4 inline-flex min-h-10 items-center gap-2 font-bold text-primary">Check eligibility <ArrowRight size={16} /></Link></div>}</section>
    <section className="mt-9 rounded-2xl border border-border bg-card p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="text-xs font-extrabold uppercase tracking-[.15em] text-primary">Upcoming dates</p><h2 className="mt-1 font-[var(--app-font-serif)] text-2xl font-extrabold">Keep an eye on these</h2></div><Link href="/deadlines" className="text-sm font-bold text-primary">All dates</Link></div>{data.upcomingDeadlines.length ? <div className="mt-4 divide-y divide-border">{data.upcomingDeadlines.slice(0,3).map(d=><div key={d.id} className="flex flex-wrap items-center justify-between gap-3 py-4"><div><p className="font-bold">{d.schemeName}</p><p className="mt-1 text-sm text-muted-foreground">{d.deadline} · {d.daysRemaining} days remaining</p></div><DataMark status={d.dataStatus} /></div>)}</div> : <p className="mt-4 text-sm text-muted-foreground">No upcoming dates are listed. Dates can change; confirm with the scheme source.</p>}</section>
  </>;
}

function SchemesPage() {
  const [q, setQ] = useState(''); const [category, setCategory] = useState(''); const [state, setState] = useState('');
  const params = useMemo(() => ({ ...(q ? { q } : {}), ...(category ? { category } : {}), ...(state ? { state } : {}) }), [q, category, state]);
  const { data, isLoading, isError, refetch } = useListSchemes(params);
  const { data: saved } = useListSavedSchemes();
  const save = useSaveScheme(); const remove = useRemoveSavedScheme();
  const client = useQueryClient();
  const savedIds = new Set((saved ?? []).map((x: any) => typeof x === 'string' ? x : x.id ?? x.scheme?.id));
  const onSave = (id: string) => (savedIds.has(id) ? remove.mutate({ schemeId: id }, { onSuccess: () => client.invalidateQueries({ queryKey: getListSavedSchemesQueryKey() }) }) : save.mutate({ schemeId: id }, { onSuccess: () => client.invalidateQueries({ queryKey: getListSavedSchemesQueryKey() }) }));
  const cats = Array.from(new Set((data ?? []).map(s => s.category)));
  const states = Array.from(new Set((data ?? []).map(s => s.state).filter(Boolean))) as string[];
  return <><PageTitle eyebrow="Scheme catalogue" title="Find a scheme to explore" sub="Search by need, category or state. Scheme information is guidance; confirm every detail with the source." />
    <div className="mb-5 grid gap-3 rounded-2xl border border-border bg-card p-4 md:grid-cols-[1fr_210px_210px]"><label className="relative"><span className="sr-only">Search schemes</span><Search size={18} className="absolute left-3 top-3.5 text-muted-foreground" /><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Try education, farming, housing…" className="min-h-11 w-full rounded-xl border border-input bg-background pl-10 pr-3 text-sm" data-testid="input-search-schemes" /></label><label><span className="sr-only">Filter category</span><select value={category} onChange={e=>setCategory(e.target.value)} className="min-h-11 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">All categories</option>{cats.map(c=><option key={c}>{c}</option>)}</select></label><label><span className="sr-only">Filter state</span><select value={state} onChange={e=>setState(e.target.value)} className="min-h-11 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">All states</option>{states.map(s=><option key={s}>{s}</option>)}</select></label></div>
    {isLoading ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{[1,2,3,4].map(n=><Skeleton key={n} className="h-72" />)}</div> : isError ? <LoadError retry={()=>refetch()} /> : !data?.length ? <div className="rounded-2xl border border-dashed border-border bg-card p-12 text-center"><Filter className="mx-auto text-primary" /><h2 className="mt-3 font-bold">No matching schemes found</h2><p className="mt-1 text-sm text-muted-foreground">Try a broader search or clear a filter.</p><Button variant="secondary" className="mt-4" onClick={()=>{setQ('');setCategory('');setState('');}}>Clear filters</Button></div> : <><p className="mb-4 text-sm text-muted-foreground">{data.length} scheme{data.length === 1 ? '' : 's'} to explore</p><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{data.map(s=><SchemeCard key={s.id} scheme={s} saved={savedIds.has(s.id)} onSave={onSave} />)}</div></>}
  </>;
}

function SchemeDetailPage() {
  const { id = '' } = useParams<{ id: string }>();
  const { data: scheme, isLoading, isError, refetch } = useGetScheme(id);
  const save = useSaveScheme(); const remove = useRemoveSavedScheme(); const { data: saved } = useListSavedSchemes(); const qc = useQueryClient();
  if (isLoading) return <Skeleton className="h-[540px]" />;
  if (isError || !scheme) return <LoadError retry={()=>refetch()} />;
  const savedNow = (saved ?? []).some((x: any) => (typeof x === 'string' ? x : x.id ?? x.scheme?.id) === scheme.id);
  const toggle = () => (savedNow ? remove.mutate({ schemeId: id }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListSavedSchemesQueryKey() }) }) : save.mutate({ schemeId: id }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListSavedSchemesQueryKey() }) }));
  return <><Link href="/schemes" className="mb-6 inline-flex items-center gap-2 text-sm font-bold text-primary"><ChevronRight className="rotate-180" size={16} />Back to schemes</Link><div className="rounded-3xl border border-border bg-card p-6 shadow-sm sm:p-9"><div className="flex flex-wrap items-center gap-3"><span className="rounded-md bg-emerald-50 px-2.5 py-1 text-xs font-bold text-primary">{scheme.category}</span><DataMark status={scheme.dataStatus} /></div><h1 className="mt-5 max-w-4xl font-[var(--app-font-serif)] text-3xl font-extrabold leading-tight sm:text-5xl">{scheme.schemeName}</h1><p className="mt-4 max-w-3xl text-lg leading-8 text-muted-foreground">{scheme.description}</p><div className="mt-6 flex flex-wrap gap-3"><Button onClick={toggle}><Heart size={17} fill={savedNow ? 'currentColor' : 'none'} />{savedNow ? 'Remove from saved' : 'Save this scheme'}</Button><Link href="/eligibility" className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-border bg-background px-4 text-sm font-bold"><ClipboardCheck size={17} />Check how it may fit</Link></div></div>
    <Alert tone="warning">This listing is marked DEMO / not currently verified. The criteria, benefit and date below may not reflect current official rules. Eligibility guidance does not mean you are approved.</Alert>
    <div className="mt-6 grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><div className="grid gap-5">
      <section className="rounded-2xl border border-border bg-card p-6"><h2 className="font-[var(--app-font-serif)] text-2xl font-extrabold">Who this may be for</h2><p className="mt-3 leading-7 text-muted-foreground">{scheme.eligibilitySummary}</p><div className="mt-5 grid gap-3 sm:grid-cols-2">{[['Age', scheme.ageMin || scheme.ageMax ? `${scheme.ageMin ?? 'No minimum listed'} to ${scheme.ageMax ?? 'No maximum listed'}` : 'Not listed'],['Gender',scheme.gender || 'Not listed'],['Occupation',scheme.occupation || 'Not listed'],['Income limit',scheme.incomeLimit ? `₹${scheme.incomeLimit.toLocaleString('en-IN')} per year` : 'Not listed'],['Category',scheme.categoryRequirement || 'Not listed'],['Land',scheme.landRequirement || 'Not listed']].map(([k,v])=><div key={k} className="rounded-xl bg-muted p-3"><p className="text-[11px] font-bold uppercase tracking-wider text-muted-foreground">{k}</p><p className="mt-1 text-sm font-semibold">{v}</p></div>)}</div></section>
      <section className="rounded-2xl border border-border bg-card p-6"><h2 className="font-[var(--app-font-serif)] text-2xl font-extrabold">What you may need</h2><ul className="mt-4 grid gap-2">{scheme.documentsRequired.map((d,i)=><li key={`${d}-${i}`} className="flex items-center gap-3 rounded-xl border border-border p-3 text-sm"><FileCheck2 size={17} className="text-primary" />{d}</li>)}</ul></section>
      <section className="rounded-2xl border border-border bg-card p-6"><h2 className="font-[var(--app-font-serif)] text-2xl font-extrabold">Application guidance</h2><ol className="mt-4 grid gap-3">{scheme.applicationSteps.map((step,i)=><li key={step} className="flex gap-3 text-sm leading-6"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-full bg-[#e8efdf] font-mono text-xs font-bold text-primary">{i+1}</span>{step}</li>)}</ol>{scheme.applicationUrl && <a href={scheme.applicationUrl} target="_blank" rel="noreferrer" className="mt-5 inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary px-4 text-sm font-bold text-white">Open application source <ExternalLink size={15} /></a>}</section>
    </div><aside className="grid content-start gap-5"><section className="rounded-2xl bg-[#173d32] p-6 text-white"><p className="text-xs font-bold uppercase tracking-widest text-[#f0ca7a]">Potential benefit</p><p className="mt-3 text-xl font-bold leading-7">{scheme.benefit}</p><p className="mt-4 border-t border-white/20 pt-4 text-sm leading-6 text-white/75">Benefit values are shown as provided in this listing. Please verify with the issuing authority.</p></section><section className="rounded-2xl border border-border bg-card p-6"><h2 className="font-bold">Source and freshness</h2><p className="mt-3 text-sm text-muted-foreground">Issuing body</p><p className="font-semibold">{scheme.government}</p><p className="mt-3 text-sm text-muted-foreground">Source</p>{scheme.sourceUrl ? <a href={scheme.sourceUrl} target="_blank" rel="noreferrer" className="break-all text-sm font-bold text-primary">{scheme.sourceName || scheme.sourceUrl} <ExternalLink className="inline" size={13} /></a> : <p className="text-sm">No source link listed</p>}<p className="mt-3 text-sm text-muted-foreground">Last updated</p><p className="text-sm font-semibold">{scheme.sourceLastUpdated || 'Not provided'}</p><div className="mt-4"><DataMark status={scheme.dataStatus} /></div>{scheme.deadline && <p className="mt-4 text-sm"><strong>Listed date:</strong> {scheme.deadline} (verify before acting)</p>}</section></aside></div>
  </>;
}

function EligibilityPage() {
  const { data: profile } = useGetProfile();
  const { data: schemes = [] } = useListSchemes();
  const check = useCheckEligibility();
  const [selected, setSelected] = useState(''); const [results, setResults] = useState<EligibilityResult[] | null>(null);
  const [form, setForm] = useState<ProfileInput>({ fullName: profile?.fullName ?? '', age: profile?.age ?? undefined, gender: profile?.gender ?? undefined, state: profile?.state ?? undefined, annualIncome: profile?.annualIncome ?? undefined, occupation: profile?.occupation ?? undefined, category: profile?.category ?? undefined, landAcres: profile?.landAcres ?? undefined, studentStatus: profile?.studentStatus, disabilityStatus: profile?.disabilityStatus, seniorCitizenStatus: profile?.seniorCitizenStatus, widowStatus: profile?.widowStatus });
  const set = (key: keyof ProfileInput, value: string) => setForm(x=>({...x,[key]: ['age','annualIncome','landAcres'].includes(key) ? (value ? Number(value) : undefined) : value || undefined}));
  const run = (e: React.FormEvent) => { e.preventDefault(); check.mutate({ data: { profile: form, ...(selected ? { schemeId: selected } : {}) } }, { onSuccess: setResults }); };
  return <><PageTitle eyebrow="Eligibility guide" title="See how your situation may fit" sub="We compare the information you provide with scheme criteria and show what matches, what does not, and what is still unknown." />
    <Alert>Results are an initial guide, not a government decision. Scheme data may be demo or unverified. Do not share sensitive numbers such as Aadhaar here.</Alert>
    <form onSubmit={run} className="mt-6 rounded-2xl border border-border bg-card p-5 sm:p-7"><h2 className="font-[var(--app-font-serif)] text-2xl font-extrabold">Tell us the basics</h2><p className="mt-1 text-sm text-muted-foreground">Fields are optional unless you need a more specific comparison.</p><div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{[
      ['age','Age','number'],['gender','Gender','text'],['state','State','text'],['annualIncome','Annual household income (₹)','number'],['occupation','Occupation','text'],['category','Social category, if relevant','text'],['landAcres','Land held in acres','number']
    ].map(([key,label,type])=><label key={key} className="grid gap-1.5 text-sm font-semibold">{label}<input type={type} min={type==='number'?'0':undefined} value={(form as any)[key] ?? ''} onChange={e=>set(key as keyof ProfileInput,e.target.value)} className="min-h-11 rounded-xl border border-input bg-background px-3 font-normal" /></label>)}</div><div className="mt-4 grid gap-3 sm:grid-cols-2">{[['studentStatus','I am currently a student'],['disabilityStatus','I have a disability'],['seniorCitizenStatus','I am a senior citizen'],['widowStatus','I am widowed']].map(([key,label])=><label key={key} className="flex min-h-11 items-center gap-3 rounded-xl border border-border px-3 text-sm"><input type="checkbox" checked={Boolean((form as any)[key])} onChange={e=>setForm(x=>({...x,[key]:e.target.checked}))} className="h-4 w-4 accent-[#28614d]" />{label}</label>)}</div><label className="mt-4 grid max-w-md gap-1.5 text-sm font-semibold">Check one specific scheme (optional)<select value={selected} onChange={e=>setSelected(e.target.value)} className="min-h-11 rounded-xl border border-input bg-background px-3 font-normal"><option value="">Compare all available schemes</option>{schemes.map(s=><option key={s.id} value={s.id}>{s.schemeName}</option>)}</select></label><Button type="submit" disabled={check.isPending} className="mt-6">{check.isPending ? 'Checking…' : 'Show my results'}<ArrowRight size={16} /></Button>{check.isError && <div className="mt-4"><Alert tone="error">We could not complete the comparison. Try again, or browse schemes directly.</Alert></div>}</form>
    {results && <section className="mt-8"><h2 className="mb-4 font-[var(--app-font-serif)] text-2xl font-extrabold">Your comparison</h2><div className="grid gap-4">{results.length ? results.map((r,i)=><article key={`${r.scheme.id}-${i}`} className="rounded-2xl border border-border bg-card p-5"><div className="flex flex-wrap items-center justify-between gap-3"><Link href={`/schemes/${r.scheme.id}`} className="text-lg font-extrabold text-primary">{r.scheme.schemeName}</Link><StatusPill status={r.status} /></div><div className="mt-4 grid gap-4 md:grid-cols-3">{[['Matched',r.matchedCriteria],['Needs attention',r.unmatchedCriteria],['Need to know',r.missingInformation]].map(([title,arr]:any)=><div><p className="text-xs font-extrabold uppercase tracking-wider text-muted-foreground">{title}</p><ul className="mt-2 grid gap-1 text-sm">{arr?.length ? arr.map((x:string)=><li key={x}>• {x}</li>) : <li className="text-muted-foreground">Nothing listed</li>}</ul></div>)}</div>{r.requiredDocuments?.length>0 && <p className="mt-4 text-sm"><strong>Documents to prepare:</strong> {r.requiredDocuments.join(', ')}</p>}<div className="mt-4 flex items-center gap-2 text-xs text-muted-foreground"><AlertTriangle size={14} />{r.verified ? 'Source marked verified' : 'Not verified — confirm details with the official source'}</div></article>) : <Alert>No comparison results were returned. Try another scheme or add more details.</Alert>}</div></section>}
  </>;
}

function AssistantPage() {
  const chat = useChatWithAssistant();
  const [question,setQuestion]=useState(''); const [language,setLanguage]=useState<'en'|'hi'|'te'>('en');
  const [messages,setMessages]=useState<Array<{q:string;answer?:string;sources?:any[];grounded?:boolean;error?:string}>>([]);
  const submit=(e:React.FormEvent)=>{e.preventDefault();if(!question.trim()||chat.isPending)return;const q=question.trim();setQuestion('');setMessages(x=>[...x,{q}]);chat.mutate({data:{question:q,language}},{onSuccess:r=>setMessages(x=>x.map((m,i)=>i===x.length-1?{...m,answer:r.answer,sources:r.sources,grounded:r.grounded}:m)),onError:()=>setMessages(x=>x.map((m,i)=>i===x.length-1?{...m,error:'We could not get an answer. Please try again.'}:m))});};
  return <><PageTitle eyebrow="Ask Saathi" title="Get a clear answer, in your language" sub="Ask about scheme benefits, application steps or documents. Answers are grounded in available sources whenever possible." />
    <Alert>Saathi provides information, not official advice or approval. Never enter Aadhaar numbers, bank details, passwords or other highly sensitive information.</Alert>
    <div className="mt-6 overflow-hidden rounded-2xl border border-border bg-card"><div className="flex flex-col justify-between gap-3 border-b border-border bg-[#f1f2e9] px-5 py-4 sm:flex-row sm:items-center"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-primary text-white"><MessageCircle size={20} /></span><div><p className="font-bold">Saathi assistant</p><p className="text-xs text-muted-foreground">English · हिन्दी · తెలుగు</p></div></div><label className="flex items-center gap-2 text-sm font-semibold"><Languages size={17} /><span className="sr-only">Answer language</span><select value={language} onChange={e=>setLanguage(e.target.value as any)} className="min-h-10 rounded-lg border border-border bg-card px-3"><option value="en">English</option><option value="hi">हिन्दी</option><option value="te">తెలుగు</option></select></label></div>
      <div className="grid max-h-[52vh] min-h-[300px] gap-4 overflow-y-auto p-4 sm:p-6">{messages.length===0 ? <div className="m-auto max-w-md text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#e8efdf] text-primary"><Sparkles size={25} /></div><h2 className="mt-4 font-[var(--app-font-serif)] text-xl font-extrabold">What would you like to understand?</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Try asking: “Which documents might I need for an education scheme?”</p></div> : messages.map((m,i)=><div key={`${m.q}-${i}`} className="grid gap-3"><div className="ml-auto max-w-[85%] rounded-2xl rounded-br-sm bg-primary px-4 py-3 text-sm leading-6 text-white">{m.q}</div>{m.answer ? <div className="max-w-[92%] rounded-2xl rounded-bl-sm bg-muted p-4 text-sm leading-7"><p className="whitespace-pre-wrap">{m.answer}</p><p className="mt-3 flex items-center gap-2 border-t border-border pt-3 text-xs font-bold text-muted-foreground"><ShieldCheck size={14} />{m.grounded?'Grounded response':'Source grounding could not be confirmed'}</p>{m.sources?.length ? <div className="mt-3 grid gap-2">{m.sources.map((s:any,si:number)=><div key={si} className="flex flex-wrap items-center justify-between gap-2 rounded-lg border border-border bg-card p-3 text-xs"><span className="font-bold">{s.title}</span><span className="flex items-center gap-2 text-muted-foreground">{s.lastUpdated||'Date not given'}<DataMark status={s.dataStatus}/>{s.url&&<a href={s.url} target="_blank" rel="noreferrer" className="text-primary"><ExternalLink size={14} /></a>}</span></div>)}</div>:<p className="mt-2 text-xs text-muted-foreground">No source references were returned. Please verify independently.</p>}</div>:m.error?<Alert tone="error">{m.error}</Alert>:<div className="flex items-center gap-2 text-sm text-muted-foreground"><span className="h-2 w-2 animate-pulse rounded-full bg-primary" />Preparing a sourced answer…</div>}</div>)}</div>
      <form onSubmit={submit} className="border-t border-border p-4 sm:p-5"><label htmlFor="assistant-question" className="sr-only">Your question</label><div className="flex items-end gap-2 rounded-2xl border border-input bg-background p-2"><textarea id="assistant-question" value={question} onChange={e=>setQuestion(e.target.value)} maxLength={4000} rows={2} placeholder="Type your question here…" className="min-h-12 flex-1 resize-y bg-transparent px-2 py-2 text-sm outline-none" /><Button type="submit" disabled={!question.trim()||chat.isPending} className="min-h-11 px-4"><Send size={16} />Ask</Button></div><p className="mt-2 text-right text-xs text-muted-foreground">{question.length}/4000</p></form></div>
  </>;
}

function DocumentsPage() {
  const { data: docs, isLoading,isError,refetch }=useListDocuments();
  const request=useRequestUploadUrl();const create=useCreateDocument();const verify=useVerifyDocument();const qc=useQueryClient();
  const [category,setCategory]=useState('Identity proof');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [error,setError]=useState('');
  const upload=async(file?:File)=>{if(!file)return;setError('');setMessage('');if(file.size>10485760){setError('Files must be 10 MB or smaller.');return;}const types=['application/pdf','image/jpeg','image/png'];if(!types.includes(file.type)){setError('Choose a PDF, JPG or PNG file.');return;}setBusy(true);try{const signed=await request.mutateAsync({data:{name:file.name,size:file.size,contentType:file.type as any}});const response=await fetch(signed.uploadURL,{method:'PUT',headers:{'Content-Type':file.type},body:file});if(!response.ok)throw new Error('The private file upload did not complete.');await create.mutateAsync({data:{fileName:file.name,category,objectPath:signed.objectPath,contentType:file.type,size:file.size}});await qc.invalidateQueries({queryKey:getListDocumentsQueryKey()});setMessage(`${file.name} uploaded privately.`);}catch(e){setError(e instanceof Error?e.message:'Upload failed. Please try again.');}finally{setBusy(false);}};
  return <><PageTitle eyebrow="Private documents" title="Keep useful documents together" sub="Upload supporting documents privately. You can review detected information and check for mismatches before using a document." /><Alert>Files are sent directly to private storage through a signed upload link. We do not send file bytes through the application API. Avoid Aadhaar and other highly sensitive documents unless an official process specifically requires them.</Alert>
    <section className="mt-6 rounded-2xl border border-dashed border-[#98aa9d] bg-[#f3f4ec] p-6 sm:p-8"><div className="mx-auto max-w-xl text-center"><span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#e3eadc] text-primary"><UploadCloud size={26}/></span><h2 className="mt-4 font-[var(--app-font-serif)] text-2xl font-extrabold">Upload a supporting document</h2><p className="mt-2 text-sm text-muted-foreground">PDF, JPG or PNG · Up to 10 MB</p><label className="mt-4 inline-flex min-h-11 cursor-pointer items-center gap-2 rounded-xl bg-primary px-5 text-sm font-bold text-white">{busy?'Uploading…':'Choose a file'}<FilePlus2 size={17}/><input type="file" accept=".pdf,image/jpeg,image/png" disabled={busy} onChange={e=>upload(e.target.files?.[0])} className="sr-only"/></label><label className="mt-4 grid gap-1 text-left text-sm font-semibold">Document type<select value={category} onChange={e=>setCategory(e.target.value)} className="min-h-11 rounded-xl border border-input bg-background px-3 font-normal"><option>Identity proof</option><option>Income certificate</option><option>Residence proof</option><option>Education certificate</option><option>Land record</option><option>Other</option></select></label>{message&&<p role="status" className="mt-3 text-sm font-bold text-primary">{message}</p>}{error&&<p role="alert" className="mt-3 text-sm font-bold text-rose-800">{error}</p>}</div></section>
    <section className="mt-8"><div className="mb-4 flex items-end justify-between"><div><p className="text-xs font-extrabold uppercase tracking-widest text-primary">Your documents</p><h2 className="mt-1 font-[var(--app-font-serif)] text-2xl font-extrabold">Private file cabinet</h2></div></div>{isLoading?<div className="grid gap-3">{[1,2].map(i=><Skeleton key={i} className="h-24"/>)}</div>:isError?<LoadError retry={()=>refetch()}/>:!docs?.length?<div className="rounded-2xl border border-dashed border-border bg-card p-8 text-center"><FileCheck2 className="mx-auto text-primary"/><p className="mt-3 font-bold">No documents uploaded yet</p><p className="mt-1 text-sm text-muted-foreground">Uploaded files will be listed here after they are saved.</p></div>:<div className="grid gap-3">{docs.map((d:CitizenDocument)=><article key={d.id} className="rounded-2xl border border-border bg-card p-4 sm:p-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div className="flex items-start gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#e8efdf] text-primary"><FileCheck2 size={19}/></span><div><p className="font-bold">{d.fileName}</p><p className="mt-1 text-xs text-muted-foreground">{d.category} · Uploaded {d.uploadedAt}</p></div></div><div className="flex flex-wrap items-center gap-2"><StatusPill status={d.status}/><Button variant="secondary" disabled={verify.isPending} onClick={()=>verify.mutate({id:d.id},{onSuccess:()=>qc.invalidateQueries({queryKey:getListDocumentsQueryKey()})})}>Verify details</Button><a href={`/api/documents/${encodeURIComponent(d.id)}/file`} download className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl border border-border bg-card px-4 py-2.5 text-sm font-bold text-foreground hover:bg-muted" data-testid={`download-document-${d.id}`}><Download size={16}/>Download</a></div></div>{d.detectedInformation?.length>0&&<p className="mt-3 text-sm"><strong>Detected:</strong> {d.detectedInformation.join(' · ')}</p>}{d.mismatchWarnings?.length>0&&<div className="mt-3 rounded-xl bg-amber-50 p-3 text-sm text-amber-950"><p className="flex items-center gap-2 font-bold"><AlertTriangle size={15}/>Please review</p><ul className="mt-1">{d.mismatchWarnings.map(w=><li key={w}>• {w}</li>)}</ul></div>}</article>)}</div>}</section>
  </>;
}

function SavedPage() {
  const {data:saved,isLoading,isError,refetch}=useListSavedSchemes();const remove=useRemoveSavedScheme();const qc=useQueryClient();
  const list=(saved??[]).map((x:any)=>typeof x==='string'?null:(x.scheme??x)).filter(Boolean) as Scheme[];
  return <><PageTitle eyebrow="Your shortlist" title="Saved schemes" sub="Keep promising options together while you gather information." />{isLoading?<div className="grid gap-4 md:grid-cols-2">{[1,2].map(i=><Skeleton key={i} className="h-64"/>)}</div>:isError?<LoadError retry={()=>refetch()}/>:list.length===0?<div className="rounded-2xl border border-dashed border-border bg-card p-10 text-center"><Heart className="mx-auto text-primary"/><h2 className="mt-3 font-bold">Nothing saved yet</h2><p className="mt-1 text-sm text-muted-foreground">Save a scheme from the catalogue and it will be easy to find again.</p><Link href="/schemes" className="mt-4 inline-flex min-h-10 items-center gap-2 font-bold text-primary">Explore schemes <ArrowRight size={16}/></Link></div>:<div className="grid gap-4 md:grid-cols-2">{list.map(s=><div key={s.id} className="relative"><SchemeCard scheme={s}/><Button variant="quiet" className="absolute right-5 top-[4.45rem] min-h-9 px-2 text-xs" onClick={()=>remove.mutate({schemeId:s.id},{onSuccess:()=>qc.invalidateQueries({queryKey:getListSavedSchemesQueryKey()})})}><X size={14}/>Remove</Button></div>)}</div>}</>;
}

function DeadlinesPage() {
  const {data:items,isLoading,isError,refetch}=useListDeadlines();const preference=useUpdateNotificationPreference();const [enabled,setEnabled]=useState(true);const [saved,setSaved]=useState(false);
  return <><PageTitle eyebrow="Dates & reminders" title="Keep track of important dates" sub="Dates can change, and not every programme has a deadline. Confirm dates with the official source before applying." /><Alert>Any demonstration dates shown here are not official deadlines. SchemeSaathi cannot guarantee reminders or application acceptance.</Alert><section className="mt-6 rounded-2xl border border-border bg-card p-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><h2 className="font-bold">Deadline notifications</h2><p className="mt-1 text-sm text-muted-foreground">Choose whether you want notification preferences enabled for your account.</p></div><div className="flex items-center gap-3"><label className="flex items-center gap-2 text-sm font-semibold"><input type="checkbox" checked={enabled} onChange={e=>{setEnabled(e.target.checked);setSaved(false);}} className="h-4 w-4 accent-[#28614d]"/>Enable notifications</label><Button variant="secondary" disabled={preference.isPending} onClick={()=>preference.mutate({data:{enabled}},{onSuccess:()=>setSaved(true)})}>{preference.isPending?'Saving…':'Save preference'}</Button></div></div>{saved&&<p role="status" className="mt-3 text-sm font-bold text-primary">Your preference was saved.</p>}{preference.isError&&<p role="alert" className="mt-3 text-sm text-rose-800">Could not save your preference. Please try again.</p>}</section><section className="mt-8">{isLoading?<div className="grid gap-3">{[1,2].map(i=><Skeleton key={i} className="h-24"/>)}</div>:isError?<LoadError retry={()=>refetch()}/>:!items?.length?<div className="rounded-2xl border border-dashed border-border bg-card p-9 text-center"><CalendarDays className="mx-auto text-primary"/><p className="mt-3 font-bold">No dates listed right now</p><p className="mt-1 text-sm text-muted-foreground">Check scheme details or return later for updates.</p></div>:<div className="grid gap-3">{items.map(d=><article key={d.id} className="flex flex-col justify-between gap-4 rounded-2xl border border-border bg-card p-5 sm:flex-row sm:items-center"><div className="flex items-center gap-4"><span className="grid h-12 w-12 shrink-0 place-items-center rounded-xl bg-[#e8efdf] text-primary"><CalendarDays size={22}/></span><div><h3 className="font-bold">{d.schemeName}</h3><p className="mt-1 text-sm text-muted-foreground">Listed date: {d.deadline} · {d.daysRemaining} days remaining</p></div></div><div className="flex items-center gap-2"><StatusPill status={d.status}/><DataMark status={d.dataStatus}/></div></article>)}</div>}</section></>;
}

function ProfilePage() {
  const {data:profile,isLoading,isError,refetch}=useGetProfile();const update=useUpdateProfile();const qc=useQueryClient();const [message,setMessage]=useState('');
  if(isLoading)return <Skeleton className="h-[500px]"/>;if(isError||!profile)return <LoadError retry={()=>refetch()}/>;
  const submit=(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const fd=new FormData(e.currentTarget);const data:ProfileInput={fullName:String(fd.get('fullName')||''),mobile:String(fd.get('mobile')||'')||null,age:fd.get('age')?Number(fd.get('age')):null,gender:String(fd.get('gender')||'')||null,state:String(fd.get('state')||'')||null,district:String(fd.get('district')||'')||null,mandal:String(fd.get('mandal')||'')||null,village:String(fd.get('village')||'')||null,annualIncome:fd.get('annualIncome')?Number(fd.get('annualIncome')):null,occupation:String(fd.get('occupation')||'')||null,landAcres:fd.get('landAcres')?Number(fd.get('landAcres')):null,category:String(fd.get('category')||'')||null,studentStatus:fd.get('studentStatus')==='on',disabilityStatus:fd.get('disabilityStatus')==='on',seniorCitizenStatus:fd.get('seniorCitizenStatus')==='on',widowStatus:fd.get('widowStatus')==='on'};update.mutate({data},{onSuccess:()=>{setMessage('Your profile was updated.');qc.invalidateQueries({queryKey:getGetProfileQueryKey()});qc.invalidateQueries({queryKey:getGetDashboardQueryKey()});},onError:()=>setMessage('We could not save your profile. Please try again.')});};
  const fields:[string,string,any][]=[['fullName','Full name',profile.fullName],['mobile','Mobile number',profile.mobile],['age','Age',profile.age],['gender','Gender',profile.gender],['state','State',profile.state],['district','District',profile.district],['mandal','Mandal / block',profile.mandal],['village','Village / town',profile.village],['annualIncome','Annual income (₹)',profile.annualIncome],['occupation','Occupation',profile.occupation],['landAcres','Land holding (acres)',profile.landAcres],['category','Category',profile.category]];
  return <><PageTitle eyebrow="Your details" title="Citizen profile" sub="Share only the information you are comfortable providing. These details help explain potential scheme fit." /><form onSubmit={submit} className="rounded-2xl border border-border bg-card p-5 sm:p-7"><Alert>Do not add Aadhaar, bank account details or other sensitive identifiers here. This profile does not establish eligibility.</Alert><div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{fields.map(([name,label,value])=><label key={name} className="grid gap-1.5 text-sm font-semibold">{label}<input name={name} type={['age','annualIncome','landAcres'].includes(name)?'number':'text'} min={['age','annualIncome','landAcres'].includes(name)?0:undefined} defaultValue={value??''} readOnly={name==='fullName'?false:undefined} className="min-h-11 rounded-xl border border-input bg-background px-3 font-normal"/></label>)}</div><div className="mt-5 grid gap-3 sm:grid-cols-2">{[['studentStatus','Currently a student',profile.studentStatus],['disabilityStatus','Person with disability',profile.disabilityStatus],['seniorCitizenStatus','Senior citizen',profile.seniorCitizenStatus],['widowStatus','Widowed',profile.widowStatus]].map(([name,label,value]:any)=><label key={name} className="flex min-h-11 items-center gap-3 rounded-xl border border-border px-3 text-sm"><input type="checkbox" name={name} defaultChecked={Boolean(value)} className="h-4 w-4 accent-[#28614d]"/>{label}</label>)}</div>{message&&<p role="status" className={cx('mt-4 text-sm font-bold',message.startsWith('Your')?'text-primary':'text-rose-800')}>{message}</p>}<Button className="mt-6" type="submit" disabled={update.isPending}>{update.isPending?'Saving…':'Save profile'}<Check size={16}/></Button></form></>;
}

function AdminPage() {
  const currentUser=useGetCurrentUser();const signedInUser=currentUser.data?.user;const isAdmin=signedInUser?.role==='admin';
  const {data:stats,isLoading,isError,refetch}=useGetAdminStats({query:{enabled:isAdmin,queryKey:getGetAdminStatsQueryKey()}});
  const {data:schemes=[]}=useListSchemes();const create=useCreateScheme();const update=useUpdateScheme();const del=useDeleteScheme();const bootstrap=useBootstrapAdmin();const qc=useQueryClient();const [editing,setEditing]=useState<Scheme|null>(null);const [notice,setNotice]=useState('');const [setupMessage,setSetupMessage]=useState('');
  const submitAdminSetup=(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setSetupMessage('');const form=e.currentTarget;const setupSecret=String(new FormData(form).get('setupSecret')??'');if(setupSecret.length<16){setSetupMessage('Enter the setup secret provided by the workspace owner. It must be at least 16 characters.');form.reset();return;}form.reset();bootstrap.mutate({data:{setupSecret}},{onSuccess:async response=>{setSetupMessage('First administrator setup succeeded. Refreshing your account access…');qc.setQueryData(getGetCurrentUserQueryKey(),response);await qc.invalidateQueries({queryKey:getGetCurrentUserQueryKey()});await qc.refetchQueries({queryKey:getGetCurrentUserQueryKey(),exact:true});},onError:error=>{const err=error as {message?:string;error?:string};const reason=`${err.error??''} ${err.message??''}`.toLowerCase();if(reason.includes('claim')||reason.includes('already')||reason.includes('complete'))setSetupMessage('First-admin setup has already been claimed. Contact your existing administrator for access.');else if(reason.includes('admin_setup_secret')||reason.includes('not configured')||reason.includes('missing secret'))setSetupMessage('First-admin setup is unavailable because ADMIN_SETUP_SECRET is not configured. Contact the workspace owner.');else setSetupMessage('Setup could not be completed. Confirm the setup secret with the workspace owner and try again.');}});};
  const save=(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const name=String(f.get('schemeName'));const item:SchemeInput={schemeName:name,government:String(f.get('government')||'Not specified'),category:String(f.get('category')||'General'),description:String(f.get('description')||''),benefit:String(f.get('benefit')||''),eligibilitySummary:String(f.get('eligibilitySummary')||''),documentsRequired:String(f.get('documentsRequired')||'').split('\n').filter(Boolean),applicationSteps:String(f.get('applicationSteps')||'').split('\n').filter(Boolean),status:'active',dataStatus:'demo_unverified',keywords:name.split(' '),sourceName:String(f.get('sourceName')||'')||null,sourceUrl:String(f.get('sourceUrl')||'')||null};const done=()=>{setEditing(null);setNotice('Scheme saved as DEMO / not currently verified.');qc.invalidateQueries({queryKey:getListSchemesQueryKey()});qc.invalidateQueries({queryKey:getGetAdminStatsQueryKey()});};if(editing)update.mutate({id:editing.id,data:item},{onSuccess:done,onError:()=>setNotice('Could not save the scheme.')});else create.mutate({data:item},{onSuccess:done,onError:()=>setNotice('Could not create the scheme.')});};
  if(currentUser.isLoading)return <Skeleton className="h-64"/>;
  if(!signedInUser)return <><PageTitle eyebrow="Administration" title="Sign in to continue" sub="Administrator setup is available only to a signed-in account."/><div className="max-w-2xl rounded-2xl border border-border bg-card p-6"><Alert tone={currentUser.isError?'warning':'info'}>{currentUser.isError?'We could not confirm your session. Sign in to continue with administrator setup.':'You are signed out. Sign in to continue with administrator setup.'}</Alert><Link href="/login" className="mt-5 inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary px-4 text-sm font-bold text-white"><LogIn size={16}/>Sign in</Link></div></>;
  if(!isAdmin)return <><PageTitle eyebrow="First administrator setup" title="Set up the first administrator" sub="A signed-in account can be promoted once using the setup secret configured by the workspace owner."/><div className="max-w-2xl rounded-2xl border border-border bg-card p-5 sm:p-7"><Alert>Only use a setup secret supplied securely by the workspace owner. It is sent to the server for verification, never saved in this browser, and never shown back on screen.</Alert><form onSubmit={submitAdminSetup} className="mt-6 grid gap-4"><label htmlFor="admin-setup-secret" className="grid gap-1.5 text-sm font-bold">First-admin setup secret<input id="admin-setup-secret" name="setupSecret" type="password" autoComplete="new-password" required minLength={16} maxLength={256} spellCheck={false} className="min-h-12 rounded-xl border border-input bg-background px-3 font-normal" aria-describedby="setup-secret-help"/></label><p id="setup-secret-help" className="text-xs leading-5 text-muted-foreground">At least 16 characters. Do not paste this value into a public message or share it with other citizens.</p><Button type="submit" disabled={bootstrap.isPending}>{bootstrap.isPending?'Checking setup secret…':'Set up administrator'}<ShieldCheck size={16}/></Button></form>{setupMessage&&<div className="mt-5"><Alert tone={setupMessage.startsWith('First administrator setup succeeded')?'success':setupMessage.startsWith('Setup could not')?'error':'warning'}>{setupMessage}</Alert></div>}</div></>;
  return <><PageTitle eyebrow="Administration" title="Scheme management" sub="Review catalogue records and keep source freshness visible. Scheme changes are not official approvals." action={<Button onClick={()=>setEditing({} as Scheme)}><FilePlus2 size={16}/>Add scheme</Button>}/>{isLoading?<div className="grid gap-4 sm:grid-cols-3">{[1,2,3].map(i=><Skeleton key={i} className="h-28"/>)}</div>:isError?<LoadError retry={()=>refetch()}/>:<div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-5">{[['Users',stats?.totalUsers,Users],['Schemes',stats?.totalSchemes,BookOpen],['Documents',stats?.totalDocuments,FileCheck2],['Upcoming dates',stats?.upcomingDeadlines,CalendarDays],['AI queries',stats?.aiQueries,MessageCircle]].map(([label,value,Icon]:any)=><div key={label} className="rounded-2xl border border-border bg-card p-4"><Icon className="text-primary" size={19}/><p className="mt-3 font-mono text-2xl font-bold">{value}</p><p className="text-xs text-muted-foreground">{label}</p></div>)}</div>}
    {notice&&<p role="status" className="mt-4 text-sm font-bold text-primary">{notice}</p>}
    {editing&&<form onSubmit={save} className="mt-6 rounded-2xl border border-border bg-card p-5"><div className="mb-4 flex items-center justify-between"><h2 className="font-bold">{editing.id?'Edit scheme':'Add a scheme record'}</h2><button type="button" onClick={()=>setEditing(null)} aria-label="Close scheme form"><X/></button></div><Alert>New and edited entries are marked DEMO / not currently verified. Confirmed official criteria and deadlines must be maintained at the source.</Alert><div className="mt-4 grid gap-3 sm:grid-cols-2">{[['schemeName','Scheme name'],['government','Issuing government'],['category','Category'],['sourceName','Source name'],['sourceUrl','Source URL'],['benefit','Potential benefit']].map(([key,label])=><label key={key} className="grid gap-1 text-sm font-semibold">{label}<input required={key==='schemeName'} name={key} defaultValue={(editing as any)[key]||''} className="min-h-10 rounded-lg border border-input bg-background px-3 font-normal"/></label>)}{[['description','Description'],['eligibilitySummary','Eligibility summary'],['documentsRequired','Documents (one per line)'],['applicationSteps','Application steps (one per line)']].map(([key,label])=><label key={key} className="grid gap-1 text-sm font-semibold sm:col-span-2">{label}<textarea name={key} rows={3} defaultValue={key==='documentsRequired'?((editing as any)[key]||[]).join('\n'):key==='applicationSteps'?((editing as any)[key]||[]).join('\n'):(editing as any)[key]||''} className="rounded-lg border border-input bg-background p-3 font-normal"/></label>)}</div><Button type="submit" className="mt-4" disabled={create.isPending||update.isPending}>Save demo record</Button></form>}
    <section className="mt-8 overflow-hidden rounded-2xl border border-border bg-card"><div className="border-b border-border p-5"><h2 className="font-[var(--app-font-serif)] text-2xl font-extrabold">Catalogue records</h2><p className="mt-1 text-sm text-muted-foreground">Edit or remove records; always check source, status and last-updated fields.</p></div><div className="divide-y divide-border">{schemes.map(s=><div key={s.id} className="flex flex-col justify-between gap-3 p-4 sm:flex-row sm:items-center"><div><p className="font-bold">{s.schemeName}</p><p className="mt-1 text-xs text-muted-foreground">{s.government} · {s.category} · Source last updated {s.sourceLastUpdated||'not provided'}</p><div className="mt-2"><DataMark status={s.dataStatus}/></div></div><div className="flex gap-2"><Button variant="secondary" onClick={()=>setEditing(s)}>Edit</Button><Button variant="danger" onClick={()=>{if(window.confirm(`Remove ${s.schemeName}?`))del.mutate({id:s.id},{onSuccess:()=>{qc.invalidateQueries({queryKey:getListSchemesQueryKey()});setNotice('Scheme removed.');},onError:()=>setNotice('Could not remove the scheme.')});}}>Remove</Button></div></div>)}</div>{!schemes.length&&<p className="p-6 text-sm text-muted-foreground">No scheme records are available.</p>}</section>
  </>;
}

function HelpPage() {
  const faqs=[['Does a potential match mean I will receive a benefit?','No. It is only an information guide. The relevant government department reviews applications and decides whether its current rules are met.'],['Are all scheme details official?','No. Listings explicitly labelled DEMO / not currently verified may be seeded examples. Check the linked source or contact the issuing office for current rules, dates and benefits.'],['What should I do if I do not know an answer?','Skip the field if it is optional. You can update your profile later. The eligibility guide will show which information is missing.'],['Are uploaded documents public?','No. Documents are uploaded to private storage and are associated with your account. Avoid adding highly sensitive documents unless required by an official process.'],['Which languages can I use with Saathi?','The assistant supports English, Hindi and Telugu. It shows references when available, but you should confirm important details with the source.'],['Can SchemeSaathi submit an application for me?','No. We provide guidance and links to application sources. You complete any application directly with the responsible authority.']];
  return <><PageTitle eyebrow="Help & support" title="Good questions deserve clear answers" sub="A few important things to know while exploring public benefits."/><div className="grid gap-3">{faqs.map(([q,a])=><details key={q} className="group rounded-2xl border border-border bg-card p-5"><summary className="flex cursor-pointer list-none items-center justify-between gap-4 font-bold">{q}<ChevronRight size={18} className="shrink-0 text-primary transition group-open:rotate-90"/></summary><p className="mt-3 max-w-3xl text-sm leading-7 text-muted-foreground">{a}</p></details>)}</div><section className="mt-8 rounded-2xl bg-[#173d32] p-6 text-white sm:p-8"><CircleHelp size={26} className="text-[#f0ca7a]"/><h2 className="mt-4 font-[var(--app-font-serif)] text-2xl font-extrabold">Need help with the next step?</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-white/75">Use the assistant for scheme questions, or contact the official department listed on a scheme page for application-specific advice.</p><div className="mt-5 flex flex-wrap gap-3"><Link href="/assistant" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-[#f0ca7a] px-4 text-sm font-bold text-[#183b31]">Ask Saathi <MessageCircle size={16}/></Link><Link href="/schemes" className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-white/30 px-4 text-sm font-bold">Explore schemes <ArrowRight size={16}/></Link></div></section></>;
}

function AuthPage({ register = false }: { register?: boolean }) {
  const registerMutation=useRegister();const loginMutation=useLogin();const auth=register?registerMutation:loginMutation;const [,setLocation]=useLocation();const qc=useQueryClient();const [error,setError]=useState('');
  const submit=(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setError('');const fd=new FormData(e.currentTarget);const data=register?{fullName:String(fd.get('fullName')),email:String(fd.get('email')),mobile:String(fd.get('mobile')),password:String(fd.get('password'))}:{email:String(fd.get('email')),password:String(fd.get('password'))};(auth as any).mutate({data},{onSuccess:(res:any)=>{qc.setQueryData(getGetCurrentUserQueryKey(),res);setLocation('/dashboard');},onError:()=>setError('We could not complete sign in. Check your details and try again.')});};
  return <div className="mx-auto grid min-h-[75vh] max-w-[980px] items-center gap-10 py-7 md:grid-cols-[.9fr_1.1fr]"><div><div className="mb-4 inline-flex items-center gap-2 rounded-full bg-[#e8efdf] px-3 py-1.5 text-xs font-bold text-primary"><ShieldCheck size={14}/>Secure account access</div><h1 className="font-[var(--app-font-serif)] text-4xl font-extrabold tracking-tight">{register?'Start with a little about you.':'Welcome back.'}</h1><p className="mt-4 max-w-md leading-7 text-muted-foreground">{register?'Your account lets you save schemes, manage your profile and keep private document records.':'Pick up where you left off. Your saved schemes and personal profile are tied to your account.'}</p><div className="mt-7 grid gap-3 text-sm text-muted-foreground">{['Your password is never stored in this browser.','Your session uses a secure, HttpOnly cookie.','A scheme match never guarantees government approval.'].map(t=><p key={t} className="flex gap-2"><Check className="shrink-0 text-primary" size={17}/>{t}</p>)}</div></div><form onSubmit={submit} className="rounded-3xl border border-border bg-card p-6 shadow-sm sm:p-8"><p className="text-xs font-extrabold uppercase tracking-[.16em] text-primary">{register?'Create account':'Sign in'}</p><h2 className="mt-2 font-[var(--app-font-serif)] text-2xl font-extrabold">{register?'A safer place to plan':'Your SchemeSaathi account'}</h2><div className="mt-6 grid gap-4">{register&&<label className="grid gap-1.5 text-sm font-semibold">Full name<input required name="fullName" autoComplete="name" minLength={2} className="min-h-11 rounded-xl border border-input bg-background px-3 font-normal"/></label>}<label className="grid gap-1.5 text-sm font-semibold">Email address<input required type="email" name="email" autoComplete="email" className="min-h-11 rounded-xl border border-input bg-background px-3 font-normal"/></label>{register&&<label className="grid gap-1.5 text-sm font-semibold">Mobile number<input required type="tel" name="mobile" autoComplete="tel" minLength={10} className="min-h-11 rounded-xl border border-input bg-background px-3 font-normal"/></label>}<label className="grid gap-1.5 text-sm font-semibold">Password<input required type="password" name="password" autoComplete={register?'new-password':'current-password'} minLength={register?8:1} className="min-h-11 rounded-xl border border-input bg-background px-3 font-normal"/></label></div>{error&&<p role="alert" className="mt-4 rounded-lg bg-rose-50 p-3 text-sm text-rose-900">{error}</p>}<Button type="submit" disabled={(auth as any).isPending} className="mt-6 w-full">{(auth as any).isPending?'Please wait…':register?'Create my account':'Sign in'}<ArrowRight size={16}/></Button><p className="mt-5 text-center text-sm text-muted-foreground">{register?'Already have an account?':'New to SchemeSaathi?'} <Link href={register?'/login':'/register'} className="font-bold text-primary">{register?'Sign in':'Create an account'}</Link></p><p className="mt-4 text-center text-xs text-muted-foreground">Passwords are sent only to the same-origin sign-in service and are never written to browser storage.</p></form></div>;
}

function Router() {
  return <RoutedErrorBoundary><Shell><Switch>
    <Route path="/" component={HomePage}/><Route path="/login"><AuthPage/></Route><Route path="/register"><AuthPage register/></Route>
    <Route path="/dashboard" component={DashboardPage}/><Route path="/schemes" component={SchemesPage}/><Route path="/schemes/:id" component={SchemeDetailPage}/>
    <Route path="/eligibility" component={EligibilityPage}/><Route path="/assistant" component={AssistantPage}/><Route path="/documents" component={DocumentsPage}/>
    <Route path="/saved" component={SavedPage}/><Route path="/deadlines" component={DeadlinesPage}/><Route path="/profile" component={ProfilePage}/>
    <Route path="/admin" component={AdminPage}/><Route path="/help" component={HelpPage}/><Route component={NotFound}/>
  </Switch></Shell></RoutedErrorBoundary>;
}
function RoutedErrorBoundary({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>;
}
function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router/></WouterRouter><Toaster/></TooltipProvider></QueryClientProvider>;
}

export default App;